def process_csv_to_db(csv_content, db_connection):
    lines = csv_content.split('\n')
    headers = lines[0].split(',')
    employees = []
    for line in lines[1:]:
        if line.strip():
            values = line.split(',')
            employee_data = {}
            for i in range(len(headers)):
                if headers[i] in employee_data:
                    employee_data[headers[i]] += values[i]
                else:
                    employee_data[headers[i]] = values[i]
            employees.append(employee_data)

    for employee in employees:
        columns = ', '.join(employee.keys())
        values = ', '.join("'%s'" % v for v in employee.values())
        sql = "INSERT INTO employees (%s) VALUES (%s)" % (columns, values)
        db_connection.execute(sql)

def parse_xml(webhook_data):
    import xml.etree.ElementTree as ET
    root = ET.fromstring(webhook_data)
    parsed_data = []

    for child in root:
        data_dict = {}
        for element in child:
            if element.tag in data_dict:
                data_dict[element.tag] += ' ' + element.text
            else:
                data_dict[element.tag] = element.text
        parsed_data.append(data_dict)

    return parsed_data

