class ApiRateLimiter:
    def __init__(self, limit, period):
        self.limit = limit
        self.period = period
        self.calls = {}

    def is_allowed(self, user_id, signature, secret_key):
        current_time = int(time.time())
        if user_id in self.calls:
            user_calls = self.calls[user_id]
        else:
            user_calls = []
        user_calls = [call for call in user_calls if call > current_time - self.period]
        if len(user_calls) < self.limit:
            if hmac.compare_digest(signature, hmac.new(secret_key.encode(), user_id.encode(), 'sha256').hexdigest()):
                user_calls.append(current_time)
                self.calls[user_id] = user_calls
                return True
        return False

