class RateLimiter:
    def __init__(self, limit_per_key, time_window):
        self.limit_per_key = limit_per_key
        self.time_window = time_window
        self.access_records = {}

    def is_allowed(self, key, timestamp):
        if key in self.access_records:
            self.access_records[key] = [t for t in self.access_records[key] if t > timestamp - self.time_window]
        else:
            self.access_records[key] = []

        if len(self.access_records[key]) < self.limit_per_key:
            self.access_records[key].append(timestamp)
            return True
        return False

    def is_signature_valid(self, signature, message, secret_key):
        expected_signature = hmac.new(secret_key.encode(), message.encode(), 'sha256').hexdigest()
        return hmac.compare_digest(expected_signature, signature)

