class RateLimiter:
    def __init__(self, limit):
        self.limit = limit
        self.calls = {}

    def is_allowed(self, user_id):
        if user_id in self.calls:
            if self.calls[user_id] < self.limit:
                self.calls[user_id] += 1
                return True
            else:
                return False
        else:
            self.calls[user_id] = 1
            return True

    def reset(self):
        for user_id in self.calls:
            self.calls[user_id] = 0

