def lazy_load_filesystem_tree(root):
    def recursive_load(node):
        for item in node['children']:
            if 'children' in item:
                for sub_item in recursive_load(item):
                    yield sub_item
            yield item['name']

    for file in recursive_load(root):
        yield file

