class HtmlSanitizer:
    def __init__(self):
        self.allowed_tags = ['b', 'i', 'u', 'strong']

    def sanitize(self, html):
        import re
        for tag in self.allowed_tags:
            pattern = "<%s>(.*?)</%s>" % (tag, tag)
            matches = re.findall(pattern, html)
            for match in matches:
                html = html.replace('<%s>%s</%s>' % (tag, match, tag), match)
        return html

