def build_file_tree(filesystem):
    tree = {}
    for path in filesystem:
        parts = path.split('/')
        subtree = tree
        for part in parts:
            if part in subtree:
                subtree = subtree[part]
            else:
                subtree[part] = {}
                subtree = subtree[part]
    return tree

