    reconciled_totals = {}
    for account, entries in transactions.items():
        if account not in reconciled_totals:
            reconciled_totals[account] = 0
        for entry in entries:
            if 'amount' in entry:
                reconciled_totals[account] += entry['amount']
    for account, entries in ledger.items():
