class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.calls = {"last_reset": 0, "count": 0}

    async def __aenter__(self):
        now = time.time()
        if now - self.calls["last_reset"] > self.period:
            self.calls = {"last_reset": now, "count": 0}
        if self.calls["count"] >= self.max_calls:
            await asyncio.sleep(self.period - (now - self.calls["last_reset"]))
            self.calls = {"last_reset": time.time(), "count": 0}
        self.calls["count"] += 1
        return self

    async def __aexit__(self, exc_type, exc, tb):
        pass

