import os

def load_filesystem_tree(path):
    tree = {}
    for root, dirs, files in os.walk(path):
        for d in dirs:
            if root not in tree:
                tree[root] = []
            tree[root].append(d)
        for f in files:
            if root not in tree:
                tree[root] = []
            tree[root].append(f)
    return tree

def lazy_load_tree(path):
    tree = load_filesystem_tree(path)
    for root in tree:
        for item in tree[root]:
            yield os.path.join(root, item)

