def lazy_load_tree(path="/"):
    stack = [path]
    visited = {}
    while stack:
        current_path = stack.pop()
        if current_path in visited:
            continue
        visited[current_path] = True
        yield "Visited %s" % current_path
        for item in get_children(current_path):
            stack.append(item)

def get_children(path):
