class RateLimiter:
    def __init__(self, rate_limit):
        self.rate_limit = rate_limit
        self.timestamps = {}

    async def is_allowed(self, user_id):
        current_time = time.time()
        if user_id in self.timestamps:
            if len(self.timestamps[user_id]) >= self.rate_limit:
