class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.calls = {}

    async def is_allowed(self, user_id):
        now = time.time()
        if user_id not in self.calls:
            self.calls[user_id] = []

        # Remove outdated calls
        new_call_times = []
        for call_time in self.calls[user_id]:
            if now - call_time < self.period:
                new_call_times.append(call_time)
        self.calls[user_id] = new_call_times

        if len(self.calls[user_id]) < self.max_calls:
            self.calls[user_id].append(now)
            return True
        else:
            return False

